$path = "index.html"
$b64 = ""
$bytes = [Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
Write-Output "index.html rewritten via Base64 (immune to console encoding issues). Verifying..."
$check = [System.IO.File]::ReadAllText((Join-Path (Get-Location) $path))
if ($check.Contains([char]0x20B9)) { Write-Output "Rupee symbol: OK" } else { Write-Output "Rupee symbol: MISSING - something is still wrong" }
if ($check.Contains([char]0x2014)) { Write-Output "Em-dash: OK" } else { Write-Output "Em-dash: MISSING - something is still wrong" }
Write-Output "Now run: firebase deploy --only hosting"
